<template><div class="max-w-5xl space-y-6"><section><h2 class="font-bold mb-3">已发布量表</h2><details v-for="r in rows" :key="r.id" class="border-b py-3"><summary>{{r.title}} · #{{r.id}} · {{r.target_type==='experiment'?'实验操作':'课题报告'}}</summary><div v-for="d in r.dimensions" class="py-2"><b>{{d.name}} / {{d.max}}</b><p class="whitespace-pre-wrap text-sm">{{d.desc||'历史量表未提供分档描述'}}</p></div><button class="btn-soft" @click="copy(r)">复制为新版本</button></details></section>
<section class="space-y-3"><button class="btn-soft" @click="rebalance">补齐互评分配</button><h2 class="font-bold">新量表版本</h2><label class="block">名称<input v-model="form.title" class="input"/></label><label class="block">对象<select v-model="form.target_type" class="input"><option value="experiment">实验操作</option><option value="project">课题报告</option></select></label>
<div v-for="(d,i) in form.dimensions" :key="i" class="border-b py-3 grid md:grid-cols-3 gap-3"><label>维度<input v-model="d.name" class="input"/></label><label>满分<input v-model.number="d.max" type="number" min="1" max="100" class="input"/></label><button class="justify-self-end" @click="form.dimensions.splice(i,1)" title="删除维度"><Icon name="trash" :size="16"/></button><label class="md:col-span-3">各分档表现与证据<textarea v-model="d.desc" class="input min-h-24"/></label></div>
<div class="flex gap-3"><button class="btn-soft" @click="form.dimensions.push({name:'',max:25,desc:''})"><Icon name="plus" :size="16"/>维度</button><button class="btn-primary" @click="save">发布新版本</button></div></section></div></template>
<script setup>
import {ref,onMounted} from 'vue';import {api} from '../../api';import Icon from '../../components/Icon.vue';const rows=ref([]),form=ref({title:'',target_type:'experiment',dimensions:[{name:'',max:25,desc:''}]});function copy(r){form.value={title:r.title+'（新版本）',target_type:r.target_type,dimensions:JSON.parse(JSON.stringify(r.dimensions))};}async function load(){rows.value=await api('/peer/rubrics');}async function save(){await api('/peer/rubrics',{method:'POST',body:form.value});await load();form.value={title:'',target_type:'experiment',dimensions:[{name:'',max:25,desc:''}]};}onMounted(load);
async function rebalance(){const r=await api('/peer/assignments/rebalance',{method:'POST'});alert(`新增 ${r.added} 项分配；${r.skipped} 份旧作品未绑定量表，需重新提交正式作品。`);}
</script>
